import { Barre } from 'svguitar';
import { CSSResult } from 'lit';
import { Finger } from 'svguitar';
import { LitElement } from 'lit';
import { TemplateResult } from 'lit-html';

export { Barre }

/*****
 * chordOnInstrument()()
 * - Given an instrument object (defined in the instruments array above), and a keychord
 *   (in this case, the actual notes in the chord as in `['A','C#','E']), we find the first
 *   instance of a chord note on each string.
 * - to be done: At this point, there is no "weighting". We are getting the first note in
 *   in the chord on a given string, which may or may not define the complete chord. How to
 *   weight for completeness?
 *****/
export declare const chordOnInstrument: (instrument: MuInstrument | undefined) => (chord: {
    notes: string[] | undefined;
} | undefined) => Finger[] | undefined;

/**
 * Pre-resolved chord data for a single chord.
 * Use this to inject custom/override chord fingerings from outside the component.
 */
export declare interface ChordOverride {
    /** Finger positions: [stringNumber, fret][] — 1-indexed strings, absolute frets. Use 'x' for muted, 0 for open. */
    fingers: Finger[];
    /** Barre chords */
    barres?: Barre[];
}

/**
 * ChordPro Renderer Web Component
 *
 * A Lit-based web component for rendering ChordPro formatted songs with chord diagrams.
 *
 * @element chordpro-renderer
 *
 * @fires chords-changed - Fired when the list of chords changes
 * @fires instrument-changed - Fired when the selected instrument changes
 * @fires mode-changed - Fired when the display mode changes
 * @fires chord-overrides-needed - Fired when chord list or instrument changes, so host can resolve chord data
 *
 * @example
 * ```html
 * <chordpro-renderer
 *   content="{title: Amazing Grace}\n[G]Amazing [C]grace..."
 *   instrument="ukulele"
 *   show-chords="true"
 *   chord-position="top"
 * ></chordpro-renderer>
 * ```
 */
export declare class ChordProRenderer extends LitElement {
    static styles: CSSResult;
    content: string;
    instrument: string;
    showChords: boolean;
    chordPosition: 'top' | 'right' | 'bottom' | 'inline';
    format: 'html' | 'text';
    /**
     * Additional instrument IDs to include in the instrument dropdown.
     * Use this for custom instruments registered via registerInstrument().
     * JS-only property (not an HTML attribute).
     */
    additionalInstruments: string[];
    /**
     * Pre-resolved chord data keyed by chord name.
     * When provided for a chord, bypasses chord-component's internal lookup
     * and uses chordFingers/chordBarres JS properties instead.
     * Chords not in this map fall back to chord-component's lookup by name.
     * JS-only property (not an HTML attribute).
     */
    chordOverrides: Record<string, ChordOverride> | null;
    private _mode;
    private _showChordsInternal;
    private _selectedInstrument;
    private parser;
    private htmlFormatter;
    private textFormatter;
    private readonly builtInInstrumentIds;
    /**
     * Combined list of all available instrument IDs (built-in + additional).
     */
    private get availableInstrumentIds();
    /**
     * Get the display name for an instrument ID.
     * Uses chord-component's registry, falls back to the raw ID.
     */
    private getInstrumentDisplayName;
    connectedCallback(): void;
    updated(changedProperties: Map<string, any>): void;
    private _syncedContent;
    private _syncedInstrument;
    private _syncedPosition;
    private _syncedOverrides;
    private _syncedContainer;
    private _syncHtmlContent;
    private _injectInlineDiagrams;
    private _syncInlineVisibility;
    private get formattedSheet();
    private get extractedChords();
    private handleModeChange;
    private handleInstrumentChange;
    private toggleChords;
    private renderSingleChord;
    private renderChordList;
    render(): TemplateResult<1>;
}

export declare const chords: MuChord[];

export declare const chordsPerScale: MuChordsByScale[];

export declare const chordToNotes: (chordName: string) => {
    name: string;
    notes: string[] | undefined;
};

declare interface Dictionary<T> {
    [key: string]: T;
}

/*****
 * Quick way of indexing a given note to a scale index. Thus `C` returns 3, while
 * both `C#` and `Db` return 4.
 *****/
export declare const findBase: (note: string) => number;

export { Finger }

declare type Instrument = Dictionary<InstrumentDefault>;

declare type InstrumentDefault = {
    barres: Barre[];
    fingers: Finger[];
};

export declare const instruments: MuInstrument[];

export declare const keys: MuKey[];

declare type MuChord = {
    variant: string;
    tones: number[];
};

declare type MuChordDescriptor = {
    key: string;
    chord: string;
    alt: string;
};

declare type MuChordsByScale = {
    variant: string;
    chords: string[];
};

declare type MuInstrument = {
    name: string;
    strings: string[];
    frets: number;
};

declare type MuKey = {
    key: string;
    accidental: string;
    relativeMinor: string;
};

declare type MuScale = {
    variant: string;
    tones: number[];
};

export declare const notes: string[][];

/*****
 * parseChords()
 * - Given a chordpro song file, we will have any number of [chordName] symbols
 *   inline.This function will give us a Map containing each of the unique
 *   instances of those chords.
 *****/
export declare const parseChords: (string: string) => Map<string, MuChordDescriptor>;

export declare const scales: MuScale[];

export declare const scaleTones: (base: string, variant: string) => (string | undefined)[] | undefined;

export declare const systemDefaultChords: Dictionary<Instrument>;

export { }


declare global {
    interface HTMLElementTagNameMap {
        'chordpro-renderer': ChordProRenderer;
    }
}

